BEGIN;
CREATE TABLE agent_endpoints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL,extension text NOT NULL,sip_username text NOT NULL,credential_secret_ref text NOT NULL,status text NOT NULL DEFAULT 'provisioning' CHECK(status IN('provisioning','active','disabled','revoked')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,extension),UNIQUE(tenant_id,user_id));
CREATE TABLE agent_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL,endpoint_id uuid REFERENCES agent_endpoints(id),presence text NOT NULL DEFAULT 'offline' CHECK(presence IN('offline','available','busy','break','wrap_up')),transport text CHECK(transport IN('webrtc','softphone','pstn')),connected_at timestamptz,disconnected_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE agent_endpoints ENABLE ROW LEVEL SECURITY;ALTER TABLE agent_endpoints FORCE ROW LEVEL SECURITY;ALTER TABLE agent_sessions ENABLE ROW LEVEL SECURITY;ALTER TABLE agent_sessions FORCE ROW LEVEL SECURITY;
CREATE POLICY agent_endpoints_isolation ON agent_endpoints USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY agent_sessions_isolation ON agent_sessions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
